'use client';

import { useState, useEffect } from 'react';
import { supabase } from '@/lib/supabase';
import { LogIn, LogOut, Loader2 } from 'lucide-react';
import Image from 'next/image';
import Link from 'next/link';

export default function SupabaseAuth() {
    const [user, setUser] = useState<any>(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        // Get initial session
        supabase.auth.getSession().then(({ data: { session } }) => {
            setUser(session?.user ?? null);
            setLoading(false);
        });

        // Listen for auth changes
        const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
            setUser(session?.user ?? null);
        });

        return () => subscription.unsubscribe();
    }, []);

    const signInWithGoogle = async () => {
        try {
            const { error } = await supabase.auth.signInWithOAuth({
                provider: 'google',
                options: {
                    redirectTo: `${window.location.origin}/auth/callback`,
                },
            });
            if (error) throw error;
        } catch (error) {
            console.error('Error logging in with Google:', error);
        }
    };

    const signOut = async () => {
        try {
            const { error } = await supabase.auth.signOut();
            if (error) throw error;
        } catch (error) {
            console.error('Error logging out:', error);
        }
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center p-4">
                <Loader2 className="animate-spin text-success" />
            </div>
        );
    }

    if (user) {
        return (
            <div className="bg-white rounded-3xl p-6 shadow-xl border border-light text-center">
                <div className="mb-4">
                    {user.user_metadata?.avatar_url ? (
                        <Image 
                            src={user.user_metadata.avatar_url} 
                            alt="Avatar" 
                            width={64} 
                            height={64} 
                            className="rounded-full mx-auto border-2 border-success p-1"
                        />
                    ) : (
                        <div className="w-16 h-16 rounded-full bg-soft flex items-center justify-center mx-auto text-2xl font-black">
                            {user.email?.charAt(0).toUpperCase()}
                        </div>
                    )}
                </div>
                <h3 className="font-black text-lg mb-1">{user.user_metadata?.full_name || 'Usuario'}</h3>
                <p className="text-secondary text-xs font-bold mb-6">{user.email}</p>
                
                <button 
                    onClick={signOut}
                    className="btn btn-outline-dark rounded-full w-100 py-2.5 text-xs font-black uppercase tracking-widest flex items-center justify-center gap-2"
                >
                    <LogOut size={14} /> Cerrar Sesión
                </button>
            </div>
        );
    }

    return (
        <div className="bg-white rounded-3xl p-8 shadow-xl border border-light text-center">
            <h3 className="font-black text-2xl mb-2">Bienvenido a Smarter</h3>
            <p className="text-secondary text-sm font-bold mb-8">
                Inicia sesión para acceder a tu panel de control y gestionar tus flujos.
            </p>
            
            <button 
                onClick={signInWithGoogle}
                className="btn btn-black rounded-full w-100 py-3 text-xs font-black uppercase tracking-widest flex items-center justify-center gap-3 transition-all hover-scale"
            >
                <svg className="w-4 h-4" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                    <path d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z" fill="#4285F4"/>
                    <path d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z" fill="#34A853"/>
                    <path d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z" fill="#FBBC05"/>
                    <path d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z" fill="#EA4335"/>
                </svg>
                Continuar con Google
            </button>
            <p className="text-secondary opacity-50 text-[10px] font-bold mt-6">
                Al continuar, aceptas nuestros <Link href="/terminos" className="underline">Términos</Link> y <Link href="/privacidad" className="underline">Privacidad</Link>.
            </p>
        </div>
    );
}
